DROP TABLE IF EXISTS `advice_templates`;
CREATE TABLE `advice_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category` varchar(50) DEFAULT NULL,
  `title` varchar(100) NOT NULL,
  `content` text NOT NULL,
  `language` enum('bn','en') DEFAULT 'bn',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `advice_templates` VALUES
('1', 'general', 'Diet Advice - Bengali', 'কম তেল-মসলা জাতীয় খাবার খাবেন।\nবাহিরের ভাজা-পোড়া খাবার খাবেন না।\nরাতে হালকা খাবার খাবেন।\nখাওয়ার পরপর শুইবেন না (কিছুক্ষণ পায়চারী করুন)।\nপর্যাপ্ত পানি পান করুন।', 'bn', '2026-06-17 12:16:00'),
('2', 'general', 'Exercise Advice - Bengali', 'সপ্তাহে ৫ দিন ৩০-৪০ মিনিট করে জোরে হাঁটবেন।\nহালকা ব্যায়াম করুন।\nপ্রতিদিন সকালে ১৫ মিনিট হাঁটাহাঁটি করুন।', 'bn', '2026-06-17 12:16:00'),
('3', 'general', 'Diet Advice - English', 'Eat less oily and spicy food.\nAvoid outside fried food.\nEat light meal at night.\nWalk for 10-15 minutes after meal.\nDrink adequate water.', 'en', '2026-06-17 12:16:00'),
('4', 'general', 'Exercise Advice - English', 'Walk briskly for 30-40 minutes, 5 days a week.\nDo light exercises.\nWalk for 15 minutes every morning.', 'en', '2026-06-17 12:16:00'),
('5', 'diabetes', 'Diabetes Advice - Bengali', 'নিয়মিত রক্তের সুগার পরীক্ষা করান।\nমিষ্টি জাতীয় খাবার পরিহার করুন।\nডায়াবেটিক ডায়েট মেনে চলুন।\nনির্ধারিত সময়ে ঔষধ সেবন করুন।', 'bn', '2026-06-17 12:16:00'),
('6', 'diabetes', 'Diabetes Advice - English', 'Check blood sugar regularly.\nAvoid sugary foods.\nFollow diabetic diet.\nTake medications on time.', 'en', '2026-06-17 12:16:00'),
('7', 'hypertension', 'Hypertension Advice - Bengali', 'নিয়মিত BP পরীক্ষা করান।\nলবণ কম খাবেন।\nমানসিক চাপ কমানোর চেষ্টা করুন।\nওজন নিয়ন্ত্রণে রাখুন।', 'bn', '2026-06-17 12:16:00'),
('8', 'hypertension', 'Hypertension Advice - English', 'Check BP regularly.\nReduce salt intake.\nManage stress.\nMaintain healthy weight.', 'en', '2026-06-17 12:16:00');

DROP TABLE IF EXISTS `appointments`;
CREATE TABLE `appointments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `appointment_number` varchar(20) NOT NULL,
  `patient_id` int(11) NOT NULL,
  `doctor_id` int(11) NOT NULL,
  `schedule_id` int(11) DEFAULT NULL,
  `appointment_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `session_type` enum('morning','evening') DEFAULT 'morning',
  `appointment_type` enum('regular','follow_up','emergency','walk_in','online') DEFAULT 'regular',
  `service_id` int(11) DEFAULT NULL,
  `status` enum('scheduled','confirmed','checked_in','in_progress','completed','canceled','no_show') DEFAULT 'scheduled',
  `payment_status` enum('pending','paid','partial','refunded') DEFAULT 'pending',
  `payment_method` enum('cash','card','mobile_banking','insurance','bank_transfer') DEFAULT 'cash',
  `transaction_id` varchar(100) DEFAULT NULL,
  `total_amount` decimal(10,2) DEFAULT 0.00,
  `payment_received` decimal(10,2) DEFAULT 0.00,
  `refund_amount` decimal(10,2) DEFAULT 0.00,
  `refund_status` enum('none','pending','completed') DEFAULT 'none',
  `payment_due` decimal(10,2) GENERATED ALWAYS AS (`total_amount` - `payment_received`) STORED,
  `last_payment_date` datetime DEFAULT NULL,
  `discount` decimal(10,2) DEFAULT 0.00,
  `tax` decimal(10,2) DEFAULT 0.00,
  `symptoms` text DEFAULT NULL,
  `special_note` text DEFAULT NULL,
  `cancellation_reason` text DEFAULT NULL,
  `cancellation_note` text DEFAULT NULL,
  `reminder_sent` tinyint(1) DEFAULT 0,
  `reminder_sent_at` timestamp NULL DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `appointment_number` (`appointment_number`),
  KEY `fk_appointments_service_id` (`service_id`),
  KEY `fk_appointments_patient_id` (`patient_id`),
  KEY `fk_appointments_doctor_id` (`doctor_id`),
  KEY `fk_appointments_schedule_id` (`schedule_id`),
  KEY `fk_appointments_created_by` (`created_by`),
  CONSTRAINT `fk_appointments_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_appointments_doctor_id` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_appointments_patient_id` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_appointments_schedule_id` FOREIGN KEY (`schedule_id`) REFERENCES `doctor_schedules` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

