DROP TABLE IF EXISTS `doctors`;
CREATE TABLE `doctors` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `department_id` int(11) NOT NULL,
  `specialization` varchar(100) NOT NULL,
  `qualification` text NOT NULL,
  `experience_years` int(11) DEFAULT NULL,
  `bmdc_number` varchar(50) NOT NULL,
  `consultation_fee` decimal(10,2) DEFAULT 0.00,
  `commission_per_visit` decimal(10,2) DEFAULT 0.00,
  `discount_permission` tinyint(1) DEFAULT 0,
  `max_discount_percentage` decimal(5,2) DEFAULT 0.00,
  `signature_path` varchar(255) DEFAULT NULL,
  `digital_stamp_path` varchar(255) DEFAULT NULL,
  `profile_photo` varchar(255) DEFAULT NULL,
  `bio` text DEFAULT NULL,
  `education` text DEFAULT NULL,
  `awards` text DEFAULT NULL,
  `languages` varchar(100) DEFAULT NULL,
  `total_patients` int(11) DEFAULT 0,
  `rating` decimal(2,1) DEFAULT 0.0,
  `total_reviews` int(11) DEFAULT 0,
  `status` enum('active','inactive','on_leave') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `commission_per_consultation` decimal(10,2) DEFAULT 0.00,
  `commission_per_test` decimal(10,2) DEFAULT 0.00,
  `total_commission_earned` decimal(10,2) DEFAULT 0.00,
  `total_earned_commission` decimal(10,2) DEFAULT 0.00,
  `max_patients_per_shift` int(11) DEFAULT 20,
  `slot_duration` int(11) DEFAULT 15,
  PRIMARY KEY (`id`),
  UNIQUE KEY `license_number` (`bmdc_number`),
  KEY `user_id` (`user_id`),
  KEY `department_id` (`department_id`),
  KEY `idx_bmdc_number` (`bmdc_number`),
  CONSTRAINT `doctors_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `doctors_ibfk_2` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

