DROP TABLE IF EXISTS `inventory_items`;
CREATE TABLE `inventory_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_code` varchar(50) NOT NULL,
  `barcode` varchar(100) DEFAULT NULL,
  `item_name` varchar(200) NOT NULL,
  `generic_name` varchar(200) DEFAULT NULL,
  `category_id` int(11) NOT NULL,
  `item_type` enum('medicine','consumable','surgical','equipment','other') NOT NULL DEFAULT 'other',
  `manufacturer` varchar(200) DEFAULT NULL,
  `supplier_id` int(11) DEFAULT NULL,
  `unit_of_measure` varchar(20) NOT NULL,
  `pack_size` varchar(50) DEFAULT NULL,
  `strength` varchar(50) DEFAULT NULL,
  `purchase_price` decimal(10,2) NOT NULL,
  `selling_price` decimal(10,2) NOT NULL,
  `tax_percentage` decimal(5,2) DEFAULT 0.00,
  `description` text DEFAULT NULL,
  `brand` varchar(100) DEFAULT NULL,
  `warranty` int(11) DEFAULT 0,
  `serial_number` varchar(100) DEFAULT NULL,
  `mrp` decimal(10,2) DEFAULT NULL,
  `reorder_level` int(11) DEFAULT 10,
  `reorder_quantity` int(11) DEFAULT 50,
  `min_stock_level` int(11) DEFAULT 5,
  `max_stock_level` int(11) DEFAULT 100,
  `storage_location` varchar(100) DEFAULT NULL,
  `storage_condition` varchar(100) DEFAULT NULL,
  `requires_refrigeration` tinyint(1) DEFAULT 0,
  `status` enum('active','inactive','discontinued') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `item_code` (`item_code`),
  UNIQUE KEY `barcode` (`barcode`),
  KEY `category_id` (`category_id`),
  KEY `idx_inventory_supplier` (`supplier_id`),
  CONSTRAINT `inventory_items_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `inventory_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

