DROP TABLE IF EXISTS `lab_test_order_items`;
CREATE TABLE `lab_test_order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `test_id` int(11) NOT NULL,
  `sample_barcode` varchar(100) DEFAULT NULL,
  `sample_collection_date` timestamp NULL DEFAULT NULL,
  `sample_collected_by` int(11) DEFAULT NULL,
  `result` text DEFAULT NULL,
  `result_date` timestamp NULL DEFAULT NULL,
  `result_entered_by` int(11) DEFAULT NULL,
  `is_abnormal` tinyint(1) DEFAULT 0,
  `status` enum('pending','sample_collected','processing','completed','reviewed') DEFAULT 'pending',
  `result_value` text DEFAULT NULL,
  `result_entered_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `sample_collected_at` timestamp NULL DEFAULT NULL,
  `received_at` timestamp NULL DEFAULT NULL,
  `received_by` int(11) DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `processed_by` int(11) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sample_barcode` (`sample_barcode`),
  KEY `order_id` (`order_id`),
  KEY `test_id` (`test_id`),
  KEY `sample_collected_by` (`sample_collected_by`),
  KEY `result_entered_by` (`result_entered_by`),
  CONSTRAINT `lab_test_order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `lab_test_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `lab_test_order_items_ibfk_2` FOREIGN KEY (`test_id`) REFERENCES `lab_tests` (`id`),
  CONSTRAINT `lab_test_order_items_ibfk_3` FOREIGN KEY (`sample_collected_by`) REFERENCES `users` (`id`),
  CONSTRAINT `lab_test_order_items_ibfk_4` FOREIGN KEY (`result_entered_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

