DROP TABLE IF EXISTS `lab_tests`;
CREATE TABLE `lab_tests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `test_code` varchar(20) NOT NULL,
  `test_name` varchar(200) NOT NULL,
  `test_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `category` varchar(100) DEFAULT NULL,
  `category_id` int(11) NOT NULL,
  `supplier_id` int(11) DEFAULT NULL,
  `specimen_type` varchar(100) DEFAULT NULL,
  `container_type` varchar(50) DEFAULT NULL,
  `normal_range` text DEFAULT NULL,
  `unit` varchar(50) DEFAULT NULL,
  `turnaround_time` int(11) DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `is_package` tinyint(1) DEFAULT 0,
  `requires_fasting` tinyint(1) DEFAULT 0,
  `description` text DEFAULT NULL,
  `preparation_instructions` text DEFAULT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `test_code` (`test_code`),
  KEY `category_id` (`category_id`),
  KEY `idx_lab_supplier` (`supplier_id`),
  CONSTRAINT `lab_tests_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `lab_test_categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

