DROP TABLE IF EXISTS `medicine_stock`;
CREATE TABLE `medicine_stock` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `medicine_id` int(11) NOT NULL,
  `batch_number` varchar(50) NOT NULL,
  `expiry_date` date NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `unit_of_measure` varchar(50) DEFAULT 'Strip',
  `reorder_level` int(11) DEFAULT 10,
  `purchase_price` decimal(10,2) NOT NULL,
  `selling_price` decimal(10,2) NOT NULL,
  `location` varchar(100) DEFAULT NULL,
  `status` enum('in_stock','low_stock','expired','out_of_stock') DEFAULT 'in_stock',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `manufacturing_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_expiry` (`expiry_date`),
  KEY `idx_batch` (`batch_number`),
  KEY `idx_medicine` (`medicine_id`),
  CONSTRAINT `medicine_stock_ibfk_1` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

