DROP TABLE IF EXISTS `prescription_advice`;
CREATE TABLE `prescription_advice` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prescription_id` int(11) NOT NULL,
  `advice_text` text DEFAULT NULL,
  `follow_up_days` int(11) DEFAULT 0,
  `follow_up_months` int(11) DEFAULT 0,
  `appointment_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `prescription_id` (`prescription_id`),
  KEY `idx_pa_prescription_id` (`prescription_id`),
  CONSTRAINT `prescription_advice_ibfk_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `prescription_advice` VALUES
('4', '1', 'কম তেল-মসলা জাতীয় খাবার খাবেন।\r\nরাতে হালকা খাবার খাবেন।\r\nসপ্তাহে ৫ দিন ৩০-৪০ মিনিট হাঁটবেন।', '0', '0', '2026-06-29', '2026-06-22 16:30:57', '2026-06-22 16:30:57'),
