  `drug_id` int(11) DEFAULT NULL,
  `drug_name` varchar(200) DEFAULT NULL,
  `dosage` varchar(100) NOT NULL,
  `frequency` varchar(100) NOT NULL,
  `duration` varchar(50) NOT NULL,
  `route` varchar(50) DEFAULT NULL,
  `instructions` text DEFAULT NULL,
  `relation_to_food` varchar(50) DEFAULT NULL,
  `quantity` int(11) NOT NULL,
  `refills` int(11) DEFAULT 0,
  `is_substitute_allowed` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `refill_count` int(11) DEFAULT 0,
  `refill_remaining` int(11) DEFAULT 0,
  `last_refill_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `prescription_id` (`prescription_id`),
  KEY `drug_id` (`drug_id`),
  CONSTRAINT `prescription_items_ibfk_1` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

