DROP TABLE IF EXISTS `prescriptions`;
CREATE TABLE `prescriptions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prescription_number` varchar(20) NOT NULL,
  `patient_id` int(11) NOT NULL,
  `doctor_id` int(11) NOT NULL,
  `appointment_id` int(11) DEFAULT NULL,
  `medical_record_id` int(11) DEFAULT NULL,
  `prescription_date` date NOT NULL,
  `diagnosis` text DEFAULT NULL,
  `follow_up_days` int(11) DEFAULT 0,
  `appointment_date` date DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `status` enum('draft','issued','dispensed','completed','canceled') DEFAULT 'draft',
  `pharmacy_status` enum('pending','processing','ready','dispensed','collected') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `visit_number` int(11) DEFAULT 1,
  `marital_status` enum('single','married','divorced','widowed') DEFAULT NULL,
  `occupation` varchar(100) DEFAULT NULL,
  `special_note` text DEFAULT NULL,
  `physical_exam_id` int(11) DEFAULT NULL,
  `vital_signs_id` int(11) DEFAULT NULL,
  `advice_id` int(11) DEFAULT NULL,
  `printed_count` int(11) DEFAULT 0,
  `last_printed_at` timestamp NULL DEFAULT NULL,
  `cancellation_reason` text DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `duplicated_from` int(11) DEFAULT NULL,
  `is_duplicate` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `prescription_number` (`prescription_number`),
  KEY `appointment_id` (`appointment_id`),
  KEY `medical_record_id` (`medical_record_id`),
  KEY `idx_doctor_status` (`doctor_id`,`status`),
  KEY `idx_patient_date` (`patient_id`,`prescription_date`),
  KEY `idx_pharmacy_status` (`pharmacy_status`),
  KEY `idx_prescription_number` (`prescription_number`),
  CONSTRAINT `prescriptions_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`),
  CONSTRAINT `prescriptions_ibfk_2` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`id`),
  CONSTRAINT `prescriptions_ibfk_3` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`),
  CONSTRAINT `prescriptions_ibfk_4` FOREIGN KEY (`medical_record_id`) REFERENCES `medical_records` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

